"use client";

import { useAuth } from "@clerk/nextjs";
import Link from "next/link";
import { type FormEvent, useMemo, useState } from "react";
import { useMutation, useQuery } from "convex/react";
import { api } from "@/convex/_generated/api";
import type { Id } from "@/convex/_generated/dataModel";
import { formatDate, formatPrice } from "@/lib/format";
import { AdminPageHeader } from "@/components/dashboard/admin/admin-page-header";
import type { VendorSection } from "@/components/dashboard/role-section-page";
import { WorkspaceLoadingState } from "@/components/dashboard/workspace/workspace-states";

const statuses = ["pending", "confirmed", "processing", "shipped", "delivered", "cancelled"] as const;
type OrderStatus = (typeof statuses)[number];

export function VendorWorkspace({ section }: { section: VendorSection }) {
  const { isLoaded: authLoaded, isSignedIn } = useAuth();
  const canQueryProtectedData = authLoaded && isSignedIn;
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const [stockDrafts, setStockDrafts] = useState<Record<string, string>>({});
  const [showForm, setShowForm] = useState(false);
  const [campaignForm, setCampaignForm] = useState({ name: "", headline: "", description: "", channel: "storefront" as "storefront" | "email" | "social", budget: "" });
  const [profileForm, setProfileForm] = useState({ brandName: "", contactEmail: "", phone: "", bio: "" });
  const orderStatus = statuses.includes(status as OrderStatus) ? status as OrderStatus : undefined;
  const orders = useQuery(api.vendor.orders, canQueryProtectedData && section === "orders" ? { status: orderStatus } : "skip");
  const products = useQuery(api.vendor.products, canQueryProtectedData && ["products", "inventory"].includes(section) ? { search: search || undefined, alertsOnly: section === "inventory", ownedOnly: section === "inventory" } : "skip");
  const collections = useQuery(api.vendor.collections, canQueryProtectedData && section === "collections" ? {} : "skip");
  const campaigns = useQuery(api.campaigns.list, canQueryProtectedData && section === "marketing" ? {} : "skip");
  const analytics = useQuery(api.analytics.summary, canQueryProtectedData && section === "analytics" ? {} : "skip");
  const snapshots = useQuery(api.analytics.snapshots, canQueryProtectedData && section === "analytics" ? {} : "skip");
  const profile = useQuery(api.vendor.profile, canQueryProtectedData && section === "settings" ? {} : "skip");
  const updateOrderStatus = useMutation(api.vendor.updateOrderStatus);
  const saveProduct = useMutation(api.vendor.saveProduct);
  const createCampaign = useMutation(api.campaigns.create);
  const updateCampaignStatus = useMutation(api.campaigns.updateStatus);
  const captureSnapshot = useMutation(api.analytics.capture);
  const saveProfile = useMutation(api.vendor.saveProfile);

  const visibleProducts = useMemo(() => { const needle = search.trim().toLowerCase(); return (products ?? []).filter((product) => !needle || `${product.name} ${product.category} ${product.collection ?? ""} ${product.sku ?? ""}`.toLowerCase().includes(needle)); }, [products, search]);
  const loading = !authLoaded || !isSignedIn
    || (section === "orders" && orders === undefined)
    || (["products", "inventory"].includes(section) && products === undefined)
    || (section === "collections" && collections === undefined)
    || (section === "marketing" && campaigns === undefined)
    || (section === "analytics" && (analytics === undefined || snapshots === undefined))
    || (section === "settings" && profile === undefined);
  if (loading) return <WorkspaceLoadingState label={section.replace("-", " ")} />;
  async function run(action: () => Promise<unknown>, key: string) { setBusy(key); setError(null); try { await action(); } catch { setError("That vendor update could not be saved."); } finally { setBusy(null); } }
  async function submitCampaign(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const { budget, ...campaignValues } = campaignForm; const budgetCents = Math.round(Number(budget || 0) * 100); await run(() => createCampaign({ ...campaignValues, status: "draft", budgetCents, startsAt: Date.now(), endsAt: Date.now() + 30 * 86_400_000 }), "campaign"); setCampaignForm({ name: "", headline: "", description: "", channel: "storefront", budget: "" }); setShowForm(false); }
  async function submitProfile(event: FormEvent<HTMLFormElement>) { event.preventDefault(); await run(() => saveProfile({ brandName: profileForm.brandName || profile?.brandName || "", contactEmail: profileForm.contactEmail || profile?.contactEmail || "", phone: profileForm.phone || profile?.phone || "", bio: profileForm.bio || profile?.bio || "" }), "profile"); }

  if (section === "orders") return <section className="admin-section"><AdminPageHeader eyebrow="Vendor fulfillment" title="Orders" description="See orders containing your catalog pieces and move approved fulfillment work to its next stage." /><div className="admin-toolbar"><label className="admin-filter"><span>Status</span><select value={status} onChange={(event) => setStatus(event.target.value)}><option value="">All orders</option>{statuses.map((item) => <option key={item}>{item}</option>)}</select></label><span className="admin-toolbar-count">{orders?.length ?? 0} orders</span></div>{error && <p className="admin-error" role="alert">{error}</p>}<div className="admin-table-card"><table className="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Piece</th><th>Total</th><th>Status</th><th>Placed</th></tr></thead><tbody>{orders?.length ? orders.map((order) => <tr key={order.id}><td className="admin-order-number">#{order.orderNumber}</td><td>{order.customer}</td><td><strong>{order.itemName}</strong><small>{order.itemCount} items</small></td><td>{formatPrice(order.amountCents)}</td><td>{order.status === "pending" || order.status === "confirmed" || order.status === "processing" ? <select className={`admin-status admin-status-${order.status}`} disabled={busy === order.id} value={order.status} onChange={(event) => { const next = event.target.value; if (next === "processing" || next === "shipped") void run(() => updateOrderStatus({ orderId: order.id as Id<"orders">, status: next }), order.id); }}>{["pending", "confirmed", "processing", "shipped"].map((item) => <option key={item}>{item}</option>)}</select> : <span className={`admin-status admin-status-${order.status}`}>{order.status}</span>}</td><td>{formatDate(order.createdAt, { month: "short", day: "numeric" })}</td></tr>) : <tr><td colSpan={6}><span className="admin-empty">No orders currently include one of your assigned catalog pieces.</span></td></tr>}</tbody></table></div></section>;

  if (section === "products") return <section className="admin-section"><AdminPageHeader eyebrow="Your catalog" title="Products" description="Manage the pieces available to your storefront partnership. Unassigned catalog pieces can be claimed when you first save them." /><label className="admin-search"><span aria-hidden="true">⌕</span><span className="sr-only">Search vendor products</span><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search your catalog" /></label>{error && <p className="admin-error" role="alert">{error}</p>}<div className="admin-table-card"><table className="admin-table"><thead><tr><th>Product</th><th>SKU / Category</th><th>Price</th><th>On hand</th><th>Ownership</th><th>Actions</th></tr></thead><tbody>{visibleProducts.length ? visibleProducts.map((product) => <tr key={product._id}><td><Link className="admin-text-link" href={`/products/${product.slug}`}>{product.name} ↗</Link><small>{product.collection ?? "Unassigned"}</small></td><td><strong>{product.sku ?? "—"}</strong><small>{product.category}</small></td><td>{formatPrice(product.priceCents)}</td><td><label className="sr-only" htmlFor={`vendor-stock-${product._id}`}>Stock for {product.name}</label><input className="admin-table-input admin-stock-input" id={`vendor-stock-${product._id}`} min="0" type="number" value={stockDrafts[product._id] ?? product.stock ?? 0} onChange={(event) => setStockDrafts((current) => ({ ...current, [product._id]: event.target.value }))} /></td><td><span className={`admin-stock-status${product.owned ? "" : " is-low"}`}>{product.owned ? "Managed" : "Available to claim"}</span></td><td><button className="admin-table-action" disabled={busy === product._id} type="button" onClick={() => void run(() => saveProduct({ productId: product._id, stock: Number(stockDrafts[product._id] ?? product.stock ?? 0) }), product._id)}>{busy === product._id ? "Saving…" : product.owned ? "Save stock" : "Claim & save"}</button></td></tr>) : <tr><td colSpan={6}><span className="admin-empty">No catalog pieces match this view.</span></td></tr>}</tbody></table></div></section>;

  if (section === "collections") return <section className="admin-section"><AdminPageHeader eyebrow="Collection planning" title="Collections" description="Understand where your pieces sit in the current editorial assortment and how much inventory each story holds." /><div className="admin-collection-grid">{collections?.map((collection) => <article className="admin-collection-card" key={collection._id}><div className="admin-collection-card-top"><span className="admin-collection-mark" aria-hidden="true">✦</span><span>{collection.productCount} pieces</span></div><h3>{collection.name}</h3><p>{collection.description}</p><p className="staff-collection-stat">{collection.inventoryUnits} units on hand</p><Link className="admin-text-link" href="/dashboard/vendor/products">Review catalog ↗</Link></article>)}</div></section>;

  if (section === "inventory") return <section className="admin-section"><AdminPageHeader eyebrow="Vendor stock" title="Inventory" description="Your low-stock view is ordered by urgency so replenishment decisions stay close to the data." /><div className="admin-toolbar"><label className="admin-search"><span aria-hidden="true">⌕</span><span className="sr-only">Search vendor inventory</span><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search inventory" /></label><span className="admin-toolbar-count">{visibleProducts.length} alerts</span></div>{error && <p className="admin-error" role="alert">{error}</p>}<div className="admin-table-card"><table className="admin-table"><thead><tr><th>Product</th><th>Category</th><th>On hand</th><th>Save stock</th><th>Health</th></tr></thead><tbody>{visibleProducts.map((product) => <tr key={product._id}><td><strong>{product.name}</strong><small>{product.owned ? "Your managed piece" : "Available to claim"}</small></td><td>{product.category}</td><td>{product.stock ?? 0}</td><td><form className="admin-inline-form" onSubmit={(event) => { event.preventDefault(); void run(() => saveProduct({ productId: product._id, stock: Number(stockDrafts[product._id] ?? product.stock ?? 0) }), product._id); }}><label className="sr-only" htmlFor={`vendor-inventory-${product._id}`}>Stock for {product.name}</label><input id={`vendor-inventory-${product._id}`} min="0" type="number" value={stockDrafts[product._id] ?? product.stock ?? 0} onChange={(event) => setStockDrafts((current) => ({ ...current, [product._id]: event.target.value }))} /><button type="submit" disabled={busy === product._id}>{busy === product._id ? "…" : "Save"}</button></form></td><td><span className={`admin-stock-status${(product.stock ?? 0) <= 7 ? " is-critical" : " is-low"}`}>{(product.stock ?? 0) <= 7 ? "Critical" : "Low stock"}</span></td></tr>)}</tbody></table></div></section>;

  if (section === "marketing") return <section className="admin-section"><AdminPageHeader eyebrow="Brand storytelling" title="Marketing" description="Create campaign ideas around your pieces and keep their live, scheduled, and draft states visible." action={<button className="admin-button" type="button" onClick={() => setShowForm((current) => !current)}>{showForm ? "Close form" : "New campaign"} <span aria-hidden="true">{showForm ? "×" : "＋"}</span></button>} />{showForm && <form className="admin-form-card" onSubmit={(event) => void submitCampaign(event)}><div className="admin-form-grid"><label className="admin-form-field"><span>Campaign name</span><input required value={campaignForm.name} onChange={(event) => setCampaignForm((current) => ({ ...current, name: event.target.value }))} /></label><label className="admin-form-field"><span>Channel</span><select value={campaignForm.channel} onChange={(event) => setCampaignForm((current) => ({ ...current, channel: event.target.value as typeof current.channel }))}><option value="storefront">Storefront</option><option value="email">Email</option><option value="social">Social</option></select></label><label className="admin-form-field"><span>Budget (USD)</span><input min="0" step="0.01" type="number" value={campaignForm.budget} onChange={(event) => setCampaignForm((current) => ({ ...current, budget: event.target.value }))} /></label><label className="admin-form-field admin-form-field-wide"><span>Headline</span><input required value={campaignForm.headline} onChange={(event) => setCampaignForm((current) => ({ ...current, headline: event.target.value }))} /></label><label className="admin-form-field admin-form-field-wide"><span>Description</span><textarea rows={3} value={campaignForm.description} onChange={(event) => setCampaignForm((current) => ({ ...current, description: event.target.value }))} /></label></div><button className="admin-button" disabled={busy === "campaign"} type="submit">{busy === "campaign" ? "Creating…" : "Create campaign"}</button></form>}{error && <p className="admin-error" role="alert">{error}</p>}<div className="admin-table-card"><table className="admin-table"><thead><tr><th>Campaign</th><th>Channel</th><th>Budget</th><th>Status</th></tr></thead><tbody>{campaigns?.length ? campaigns.map((campaign) => <tr key={campaign._id}><td><strong>{campaign.name}</strong><small>{campaign.headline}</small></td><td>{campaign.channel}</td><td>{formatPrice(campaign.budgetCents)}</td><td><select className="admin-status admin-status-pending" value={campaign.status} onChange={(event) => void run(() => updateCampaignStatus({ campaignId: campaign._id, status: event.target.value as "draft" | "scheduled" | "live" | "ended" }), String(campaign._id))}><option value="draft">Draft</option><option value="scheduled">Scheduled</option><option value="live">Live</option><option value="ended">Ended</option></select></td></tr>) : <tr><td colSpan={4}><span className="admin-empty">No vendor campaigns yet.</span></td></tr>}</tbody></table></div></section>;

  if (section === "analytics") return <section className="admin-section"><AdminPageHeader eyebrow="Vendor performance" title="Analytics" description="Capture a lightweight history of your current sales, orders, inventory, and low-stock position." action={<button className="admin-button" type="button" onClick={() => void run(() => captureSnapshot({ period: "Current period" }), "snapshot")}>{busy === "snapshot" ? "Capturing…" : "Capture snapshot"} <span aria-hidden="true">＋</span></button>} /><div className="admin-summary-grid"><article className="admin-summary-card"><span>Revenue</span><strong>{formatPrice(analytics?.revenueCents ?? 0)}</strong><small>Visible vendor order signal</small></article><article className="admin-summary-card"><span>Orders</span><strong>{analytics?.orderCount ?? 0}</strong><small>Active order history</small></article><article className="admin-summary-card"><span>Inventory</span><strong>{analytics?.inventoryUnits ?? 0}</strong><small>Units in live catalog</small></article><article className="admin-summary-card"><span>Low stock</span><strong>{analytics?.lowStock ?? 0}</strong><small>Pieces needing attention</small></article></div><div className="admin-table-card admin-analytics-list"><div className="admin-card-heading"><div><p className="admin-card-kicker">Report history</p><h3>Vendor snapshots</h3></div></div>{snapshots?.length ? <ul>{snapshots.map((snapshot) => <li key={snapshot._id}><span>{snapshot.period} · {formatDate(snapshot.capturedAt)}</span><strong>{formatPrice(snapshot.revenueCents)} · {snapshot.orderCount} orders</strong></li>)}</ul> : <p className="admin-empty">Capture a snapshot to begin tracking performance over time.</p>}</div></section>;

  return <section className="admin-section"><AdminPageHeader eyebrow="Vendor account" title="Settings" description="Keep your brand profile and partnership contact details current for the SterlingMart team." />{error && <p className="admin-error" role="alert">{error}</p>}<form className="admin-settings-card vendor-settings-form" onSubmit={(event) => void submitProfile(event)}><p className="admin-card-kicker">Partnership profile</p><h3>{profileForm.brandName || profile?.brandName || "Your vendor studio"}</h3><div className="admin-form-grid"><label className="admin-form-field"><span>Brand name *</span><input required value={profileForm.brandName || profile?.brandName || ""} onChange={(event) => setProfileForm((current) => ({ ...current, brandName: event.target.value }))} placeholder="Aurelia Atelier" /></label><label className="admin-form-field"><span>Contact email *</span><input required type="email" value={profileForm.contactEmail || profile?.contactEmail || ""} onChange={(event) => setProfileForm((current) => ({ ...current, contactEmail: event.target.value }))} /></label><label className="admin-form-field"><span>Phone</span><input value={profileForm.phone || profile?.phone || ""} onChange={(event) => setProfileForm((current) => ({ ...current, phone: event.target.value }))} /></label><label className="admin-form-field admin-form-field-wide"><span>Studio bio</span><textarea rows={4} value={profileForm.bio || profile?.bio || ""} onChange={(event) => setProfileForm((current) => ({ ...current, bio: event.target.value }))} placeholder="A short introduction to your studio." /></label></div><p className="admin-settings-note">Approval status: {profile?.approvalStatus ?? "pending"}. Catalog ownership is enforced server-side.</p><button className="admin-button" disabled={busy === "profile"} type="submit">{busy === "profile" ? "Saving…" : "Save vendor profile"}</button></form></section>;
}
